class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if (!head) return head;
        int n = 1;
        ListNode* tail = head;
        while (tail->next) {
            tail = tail->next;
            n++;
        }
        k %= n;
        if (k == 0) return head;
        tail->next = head;
        ListNode* newTail = head;
        for (int s = 0; s < n - k - 1; s++) newTail = newTail->next;
        head = newTail->next;
        newTail->next = nullptr;
        return head;
    }
};
